import assert from 'node:assert/strict';
import { test } from 'node:test';

import { buildPrimuseAlbumPalette } from '../src/lib/primuseAlbumPalette';
import { paletteContrast } from '../src/lib/playerPalette';

test('album gradient matches independent Swift Primuse tint-policy vectors', () => {
  // Generated by the actual upstream LibraryDetailTintPolicy at 294e3f5,
  // not by a second copy of this TypeScript implementation. Inputs are the
  // native extractor's final accent; applying accent shaping again changes them.
  const vectors = [
    ['#D90A40', true, '#4D212C', '#2D131A'],
    ['#D90A40', false, '#5E2736', '#37171F'],
    ['#5CC8B7', true, '#234C46', '#142C28'],
    ['#5CC8B7', false, '#2B5D55', '#193631'],
    ['#F0C749', true, '#4F4421', '#2E2713'],
    ['#F0C749', false, '#605228', '#383017'],
    ['#FFFFFF', true, '#434447', '#272829'],
    ['#FFFFFF', false, '#515357', '#2F3032'],
    ['#000000', true, '#434447', '#272829'],
    ['#000000', false, '#515357', '#2F3032'],
    ['#777777', true, '#434447', '#272829'],
    ['#777777', false, '#515357', '#2F3032'],
    ['#879AB8', true, '#373F4B', '#20252C'],
    ['#879AB8', false, '#434C5B', '#272C35'],
  ] as const;
  for (const [primary, dark, top, bottom] of vectors) {
    const result = buildPrimuseAlbumPalette(primary, dark);
    assert.equal(result.backgroundTop.toUpperCase(), top, `${primary}/${dark}: top`);
    assert.equal(result.background.toUpperCase(), bottom, `${primary}/${dark}: bottom`);
  }
});

test('white titles, secondary labels and play ink remain readable across album colors', () => {
  const levels = [0, 8, 32, 96, 160, 224, 255];
  for (const dark of [true, false]) {
    for (const red of levels) for (const green of levels) for (const blue of levels) {
      const seed = '#' + [red, green, blue].map((value) => value.toString(16).padStart(2, '0')).join('');
      const palette = buildPrimuseAlbumPalette(seed, dark);
      for (const surface of [palette.backgroundTop, palette.background]) {
        for (const ink of [palette.text, palette.textSecondary, palette.textMuted]) {
          assert.ok(paletteContrast(ink, surface) >= 4.5, `${seed}/${dark}: ${ink} on ${surface}`);
        }
      }
      assert.ok(paletteContrast(palette.playLabel, '#FFFFFF') >= 4.5);
    }
  }
});

test('missing or achromatic artwork uses the same neutral album fallback', () => {
  for (const dark of [true, false]) {
    const neutral = buildPrimuseAlbumPalette(undefined, dark);
    for (const seed of ['#000000', '#FFFFFF', '#777777', '#FEFEFE', '#GGGGGG', 'transparent', '#abc', '']) {
      assert.deepEqual(buildPrimuseAlbumPalette(seed, dark), neutral, `${seed}/${dark}`);
    }
    assert.notEqual(buildPrimuseAlbumPalette('#D90A40', dark).backgroundTop, neutral.backgroundTop);
    assert.notEqual(buildPrimuseAlbumPalette('#D90A40', dark).backgroundTop,
      buildPrimuseAlbumPalette('#0055D9', dark).backgroundTop);
  }
});

test('appearance changes recompute from the cached primary without retaining earlier roles', () => {
  const primary = '#5CC8B7';
  const dark = buildPrimuseAlbumPalette(primary, true);
  const light = buildPrimuseAlbumPalette(primary, false);
  assert.notEqual(dark.backgroundTop, light.backgroundTop);
  assert.notEqual(dark.background, light.background);
  assert.deepEqual(buildPrimuseAlbumPalette(primary, true), dark);
  assert.deepEqual(buildPrimuseAlbumPalette(primary, false), light);
});
